#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

OUT="sdk/typescript"
mkdir -p "$OUT"

echo "▶ Generating TypeScript types → $OUT/api.d.ts"
npx openapi-typescript openapi/api.yaml --output "$OUT/api.d.ts"

cat > "$OUT/index.ts" <<'TS'
// Auto-generated by scripts/generate-ts.sh — do not edit by hand.
export type * from './api';
TS

echo "✓ TypeScript types written to $OUT/"
